<script setup>
import { onMounted, reactive, ref } from 'vue'
import api from '../services/api'
const business = ref(null); const form = reactive({ name: '', trade_name: '', mobile: '', email: '', address: '' }); const saving = ref(false); const notice = ref('')
onMounted(async () => { const { data } = await api.get('/businesses'); business.value = data.data[0]; if (business.value) Object.assign(form, business.value) })
const save = async () => { saving.value = true; notice.value = ''; try { if (business.value) await api.put(`/businesses/${business.value.id}`, form); else { const { data } = await api.post('/businesses', form); business.value = data.data } notice.value = 'ব্যবসার তথ্য সফলভাবে সংরক্ষিত হয়েছে।' } finally { saving.value = false } }
</script>
<template><section class="page-card"><div class="page-heading"><div><p class="eyebrow">SETTINGS</p><h2>ব্যবসা প্রোফাইল</h2><p>আপনার প্রতিষ্ঠান সম্পর্কে মূল তথ্য পরিচালনা করুন।</p></div><span class="status active">● সক্রিয়</span></div><form class="form-grid" @submit.prevent="save"><label>ব্যবসার নাম<input v-model="form.name" required placeholder="রহমান ডিস্ট্রিবিউশন" /></label><label>ট্রেড নাম<input v-model="form.trade_name" placeholder="Rahman Distribution" /></label><label>মোবাইল নম্বর<input v-model="form.mobile" placeholder="01700000000" /></label><label>ইমেইল<input v-model="form.email" type="email" placeholder="info@company.com" /></label><label class="full-width">ঠিকানা<textarea v-model="form.address" rows="3" placeholder="ঢাকা, বাংলাদেশ"></textarea></label><div class="full-width form-actions"><span v-if="notice" class="success">✓ {{ notice }}</span><button class="primary" :disabled="saving">{{ saving ? 'সংরক্ষণ হচ্ছে...' : 'পরিবর্তন সংরক্ষণ করুন' }}</button></div></form></section></template>
